// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let thickness = 8, radius = 640;

let pal = ['#ECAA9C', '#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

// function mousePressed() {
// 	redraw();
// }

function setup() {
  createCanvas(w, h);
  noLoop();
  pixelDensity(2);
  smooth();
  strokeCap(SQUARE);
  colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  background(220);

  drawWaves();

  drawTrianlge();
  drawCircles();

  glich();

  drawGrids();
  drawFrame();
}

function drawCircles() {
  var step = radius / thickness;
  var c1, c2, f1, f2, type, rr;
  var margin = 2, branch1, branch2;
  var vx, vy;

  push();
  translate(w/2, h/2);

  noFill();
  for(let i = 0; i < step/2-1; i ++) {
    // translate(thickness, 0);
    rr = thickness-margin;
    strokeWeight(rr);
    noFill();

    branch1 = random(-PI * 5/6, -PI * 1/6);
    branch2 = random(PI * 1/6, PI * 5/6);

    c1 = getColor();
    stroke(c1);
    if(random() < 0.8) {
      arc(0, 0, radius, radius, branch1, 0); // migi ue    
    }
    if(random() < 0.8) {
      arc(0, 0, radius, radius, branch2, PI); // hidari sita
    }

    c2 = getColor();
    stroke(c2);
    if(random() < 0.8) {
      arc(0, 0, radius, radius, -PI, branch1); // hidari ue
    }
    if(random() < 0.8) {
      arc(0, 0, radius, radius, 0, branch2); // migi sita
    }

    noStroke();

    type = random();
    if(type < 1/2) {
      fill(c1);
    } else {
      fill(c2);
    }
    circle(radius/2, 0, rr-margin);

    type = random();
    if (type < 1/2) {
      fill(c1);
    } else  {
      fill(c2);
    }
    circle(-radius/2, 0, rr-margin);

    type = random();
    if (type < 1/2) {
      fill(c1);
    } else  {
      fill(c2);
    }
    vx = radius/2 * cos(branch1);
    vy = radius/2 * sin(branch1);
    circle(vx, vy, rr-margin);

    type = random();
    if (type < 1/2) {
      fill(c1);
    } else  {
      fill(c2);
    }
    vx = radius/2 * cos(branch2);
    vy = radius/2 * sin(branch2);
    circle(vx, vy, rr-margin);

    radius -= thickness*2;
  }
  pop();
}

function drawWaves() {
  noStroke();
  var max = 400;
  var amp = 50;
  var radius = 5;
  var offset, col;
  var theta = TWO_PI / max;
  for(let i = -3; i < 18; i++) {
    offset = 0 * i;
    col = getColor();
    fill(col);
    for(let j = -100; j < 500; j++) {
      circle(i * 60 + amp*sin(theta * j), j*2 + offset, radius);    
    }
  }
}

function drawTrianlge() {
  var count = 30, lines;
  var nx, ny, num;
  strokeWeight(2);
  noFill();
  for(let i = 0; i < count; i++) {
    var col = getColor();
    stroke(col);
    num = int( random(10,30) );
    if(random() < 0.5) {
      nx = (random(- s*5, w/2 - s*5) / s) * s;
      ny = (random(- s*5, h/2 - s*5) / s) * s;
    } else {
      nx = (random(w/2 + s*5, w + s*5) / s) * s;
      ny = (random(h/2 + s*5, h + s*5) / s) * s;
    }
    lines = int(random(10,25));

    var pattern = random();
    if(pattern < 0.2) {
      for(let i = 0; i < lines; i++) {
        line(nx, ny + i*s, nx + i*s, ny + i*s);
      }
    } else if (pattern < 0.45) {
      for(let i = 0; i < lines; i++) {
        line(nx, ny + i*s, nx - i*s, ny + i*s);
      }            
    } else if (pattern < 0.75) {
      for(let i = 0; i < lines; i++) {
        line(nx, ny - i*s, nx + i*s, ny - i*s);
      }
    } else {
      for(let i = 0; i < lines; i++) {
        line(nx, ny - i*s, nx - i*s, ny - i*s);
      }      
    }
  }
}

function glich() {
  var x1, y1, x2, y2;

  var s1 = s*8, s2 = s*4;
  for(let i = 0; i < 15; i++) {
    x1 = int(random(w/2 + s1, w) / s1) *s1;
    y1 = int(random(h/2 - s1) / s1) *s1;
    x2 = int(random(w/2 + s1, w) / s1) *s1;
    y2 = int(random(h/2 - s1) / s1) *s1;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);  
    x1 = int(random(w/2 - s1) / s1) *s1;
    y1 = int(random(h/2 + s1, h) / s1) *s1;
    x2 = int(random(w/2 - s1) / s1) *s1;
    y2 = int(random(h/2 + s1, h) / s1) *s1;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);

    x1 = int(random(w/2 + s2, w) / s2) *s2;
    y1 = int(random(h/2 - s2) / s2) *s2;
    x2 = int(random(w/2 + s2, w) / s2) *s2;
    y2 = int(random(h/2 - s2) / s2) *s2;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);  
    x1 = int(random(w/2 - s2) / s2) *s2;
    y1 = int(random(h/2 + s2, h) / s2) *s2;
    x2 = int(random(w/2 - s2) / s2) *s2;
    y2 = int(random(h/2 + s2, h) / s2) *s2;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);
  }

  s1 = s*3, s2 = s*2;
  for(let i = 0; i < 30; i++) {
    x1 = int(random(w/2 + s1, w) / s1) *s1;
    y1 = int(random(h/2 - s1) / s1) *s1;
    x2 = int(random(w/2 + s1, w) / s1) *s1;
    y2 = int(random(h/2 - s1) / s1) *s1;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);  
    x1 = int(random(w/2 - s1) / s1) *s1;
    y1 = int(random(h/2 + s1, h) / s1) *s1;
    x2 = int(random(w/2 - s1) / s1) *s1;
    y2 = int(random(h/2 + s1, h) / s1) *s1;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);

    x1 = int(random(w/2 + s2, w) / s2) *s2;
    y1 = int(random(h/2 - s2) / s2) *s2;
    x2 = int(random(w/2 + s2, w) / s2) *s2;
    y2 = int(random(h/2 - s2) / s2) *s2;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);  
    x1 = int(random(w/2 - s2) / s2) *s2;
    y1 = int(random(h/2 + s2, h) / s2) *s2;
    x2 = int(random(w/2 - s2) / s2) *s2;
    y2 = int(random(h/2 + s2, h) / s2) *s2;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);
  }

  s1 = s;
  for(let i = 0; i < 80; i++) {
    x1 = int(random(w/2 + s1, w) / s1) *s1;
    y1 = int(random(h/2 - s1) / s1) *s1;
    x2 = int(random(w/2 + s1, w) / s1) *s1;
    y2 = int(random(h/2 - s1) / s1) *s1;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);  
    x1 = int(random(w/2 - s1) / s1) *s1;
    y1 = int(random(h/2 + s1, h) / s1) *s1;
    x2 = int(random(w/2 - s1) / s1) *s1;
    y2 = int(random(h/2 + s1, h) / s1) *s1;
    copy(x1, y1, s1, s1, x2, y2, s1, s1);
  }
}

// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //

function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  } 
}

function drawFrame() {
  rectMode(CENTER);
  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getColor() {
  var l = pal.length;
  var cc = random();

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

